// seedLegacyServices переносит старые захардкоженные услуги в БД один раз:
// если в таблице services уже есть записи с parent_id = 0, повтор не выполняется.
func seedLegacyServices(db *sql.DB, logger *log.Logger) {
	var count int
	if err := db.QueryRow(`SELECT COUNT(*) FROM services WHERE parent_id=0`).Scan(&count); err != nil {
		logger.Printf("seed check: %v", err)
		return
	}
	if count > 0 {
		return
	}

	// slug-и старых услуг совпадают с адресами вида /services/1..5,
	// поэтому все внешние ссылки продолжают работать.
	for _, s := range services {
		intro := legacyServiceIntro[s.ID]
		slug := strconv.Itoa(s.ID)
		res, err := db.Exec(`INSERT INTO services(direction,title,description,slug,parent_id,status,created_at,updated_at) VALUES(?,?,?,?,0,'published',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)`,
			s.Title, s.Title, intro, slug)
		if err != nil {
			logger.Printf("seed service %d: %v", s.ID, err)
			return
		}
		parentID, err := res.LastInsertId()
		if err != nil {
			logger.Printf("seed service id %d: %v", s.ID, err)
			return
		}
		if s.ID < len(legacyServiceBlocks) {
			for _, block := range legacyServiceBlocks[s.ID] {
				if strings.TrimSpace(block.Title) == "" {
					continue
				}
				blockSlug := slugify(block.Title)
				if blockSlug == "" {
					blockSlug = "service"
				}
				if _, err := db.Exec(`INSERT INTO services(direction,title,description,slug,parent_id,status,created_at,updated_at) VALUES(?,?,?,?,?,'published',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)`,
					block.Direction, block.Title, block.Description, blockSlug, parentID); err != nil {
					logger.Printf("seed child %q: %v", block.Title, err)
					return
				}
			}
		}
	}
	logger.Printf("seed: legacy services migrated to DB")
}
